2.06 24.04L33.26 2.82Z\" fill=\"black\"/><path d=\"M31 28H3V32H31V28Z\" fill=\"black\"/></svg></mat-icon>'';\n    }\n    if (value == ''FAILED'') {\n        return ''<mat-icon _role=\"img\" class=\"mat-icon notranslate material-icons mat-icon-no-color\" aria-hidden=\"true\" data-mat-icon-type=\"font\" style=\"color: #D93025\">warning</mat-icon>'';\n    }\n    return '''';\n}\nfunction capitalize (s) {\n  if (typeof s !== ''string'') return '''';\n  return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();\n}\n\nreturn icon(value) + ''<span style=\"vertical-align: super;padding-left: 8px;\">'' + capitalize(value) + ''</span>'';"},"units":null,"decimals":null,"funcBody":null,"usePostProcessing":null,"postFuncBody":null},{"name":"sw_checksum","type":"attribute","label":"sw_checksum","color":"#3f51b5","settings":{"columnWidth":"0px","useCellStyleFunction":false,"cellStyleFunction":"","useCellContentFunction":false,"defaultColumnVisibility":"hidden","columnSelectionToDisplay":"disabled"},"units":null,"decimals":null,"funcBody":null,"usePostProcessing":null,"postFuncBody":null},{"name":"sw_url","type":"attribute","label":"sw_url","color":"#e91e63","settings":{"columnWidth":"0px","useCellStyleFunction":false,"cellStyleFunction":"","useCellContentFunction":false,"cellContentFunction":"","defaultColumnVisibility":"hidden","columnSelectionToDisplay":"disabled"},"units":null,"decimals":null,"funcBody":null,"usePostProcessing":null,"postFuncBody":null}]}],"actions":{"actionCellButton":[{"name":"History software update","icon":"history","type":"openDashboardState","targetDashboardStateId":"device_software_history","setEntityId":true,"stateEntityParamName":null,"openInSeparateDialog":false,"dialogTitle":"","dialogHideDashboardToolbar":true,"dialogWidth":null,"dialogHeight":null,"openRightLayout":false,"id":"98a1406c-3301-bc2f-2c5d-d637ce3b663b"},{"name":"Edit software","icon":"edit","type":"customPretty","customHtml":"<form #editEntityForm=\"ngForm\" [formGroup]=\"editEntityFormGroup\"\n      (ngSubmit)=\"save()\"  class=\"edit-entity-form\">\n  <mat-toolbar class=\"flex flex-row\" color=\"primary\">\n    <h2>Edit software {{entityName}}</h2>\n    <span class=\"flex-1\"></span>\n    <button mat-icon-button (click)=\"cancel()\" type=\"button\">\n      <mat-icon class=\"material-icons\">close</mat-icon>\n    </button>\n  </mat-toolbar>\n  <mat-progress-bar color=\"warn\" mode=\"indeterminate\" *ngIf=\"isLoading$ | async\">\n  </mat-progress-bar>\n  <div style=\"height: 4px;\" *ngIf=\"!(isLoading$ | async)\"></div>\n  <div *ngIf=\"entity.deviceProfileId\" mat-dialog-content class=\"flex flex-col\">\n    <tb-ota-package-autocomplete\n        [useFullEntityId]=\"true\"\n        type=\"SOFTWARE\"\n        [deviceProfileId]=\"entity.deviceProfileId.id\"\n        formControlName=\"softwareId\">\n    </tb-ota-package-autocomplete>\n  </div>\n  <div mat-dialog-actions class=\"flex flex-row items-center justify-end\">\n    <button mat-button color=\"primary\"\n            type=\"button\"\n            [disabled]=\"(isLoading$ | async)\"\n            (click)=\"cancel()\" cdkFocusInitial>\n      Cancel\n    </button>\n    <button mat-button mat-raised-button color=\"primary\"\n            type=\"submit\"\n            [disabled]=\"(isLoading$ | async) || editEntityForm.invalid || !editEntityForm.dirty\">\n      Save\n    </button>\n  </div>\n</form>","customCss":"form {\n    min-width: 300px !important;\n}","customFunction":"let $injector = widgetContext.$scope.$injector;\nlet customDialog = $injector.get(widgetContext.servicesMap.get(''customDialog''));\nlet entityService = $injector.get(widgetContext.servicesMap.get(''entityService''));\nlet deviceService = $injector.get(widgetContext.servicesMap.get(''deviceService''));\n\nopenEditEntityDialog();\n\nfunction openEditEntityDialog() {\n    customDialog.customDialog(htmlTemplate, EditEntityDialogController).subscribe();\n}\n\nfunction EditEntityDialogController(instance) {\n    let vm = instance;\n\n    vm.entityName = entityName;\n    vm.entity = {};\n\n    vm.editEntityFormGroup = vm.fb.group({\n        softwareId: [null]\n    });\n\n    getEntityInfo();\n\n    vm.cancel = function() {\n        vm.dialogRef.close(null);\n    };\n\n    vm.save = function() {\n        vm.editEntityFormGroup.markAsPristine();\n        saveEntity().subscribe(\n            function () {\n                // widgetContext.updateAliases();\n                vm.dialogRef.close(null);\n            }\n        );\n    };\n\n\n    function getEntityInfo() {\n        entityService.getEntity(entityId.entityType, entityId.id).subscribe(\n            function (data) {\n                vm.entity = data;\n                vm.editEntityFormGroup.patchValue({\n                    softwareId: vm.entity.softwareId\n                }, {emitEvent: false});\n            }\n        );\n    }\n\n    function saveEntity() {\n        const formValues = vm.editEntityFormGroup.value;\n        vm.entity.softwareId = formValues.softwareId;\n        return deviceService.saveDevice(vm.entity);\n    }\n}","customResources":[],"id":"23099c1d-454b-25dc-8bc0-7cf33c21c5d5"},{"name":"Download software","icon":"file_download","type":"custom","customFunction":"let $injector = widgetContext.$scope.$injector;\nlet entityService = $injector.get(widgetContext.servicesMap.get(''entityService''));\nlet otaPackageService = $injector.get(widgetContext.servicesMap.get(''otaPackageService''));\nlet deviceProfileService = $injector.get(widgetContext.servicesMap.get(''deviceProfileService''));\n\ngetDeviceSoftware();\n\nfunction getDeviceSoftware() {\n    var entityIdValue = entityId.id;\n    var data = widgetContext.data.find((el) => el.datasource.entityId === entityIdValue && el.dataKey.name === ''sw_url'');\n    var url = data.data[0][1];\n    if (url === '''') {\n        entityService.getEntity(entityId.entityType, entityId.id).subscribe(\n            function (data) {\n                if (data.softwareId !== null) {\n                    otaPackageService.downloadOtaPackage(data.softwareId.id).subscribe();    \n                } else {\n                    deviceProfileService.getDeviceProfile(data.deviceProfileId.id).subscribe(\n                        function (deviceProfile) {\n                            if (deviceProfile.softwareId !== null) {\n                                otaPackageService.downloadOtaPackage(deviceProfile.softwareId.id).subscribe();\n                            } else {\n                                widgetContext.showToast(''warn'', ''Device '' + entityName +'' has not software set.'', 2000, ''top'');\n                            }\n                    });\n                }\n            }\n        );\n    } else {\n        widgetContext.showToast(''warn'', ''Device '' + entityName +'' has not software set.'', 2000, ''top'');\n    }\n}","id":"12533058-42f6-e75f-620c-219c48d01ec0"},{"name":"Copy checksum/URL","icon":"content_copy","type":"custom","customFunction":"function copyToClipboard(text) {\n    if (window.clipboardData && window.clipboardData.setData) {\n        return window.clipboardData.setData(\"Text\", text);\n\n    }\n    else if (document.queryCommandSupported && document.queryCommandSupported(\"copy\")) {\n        var textarea = document.createElement(\"textarea\");\n        textarea.textContent = text;\n        textarea.style.position = \"fixed\";\n        document.body.appendChild(textarea);\n        textarea.select();\n        try {\n            return document.execCommand(\"copy\");\n        }\n        catch (ex) {\n            console.warn(\"Copy to clipboard failed.\", ex);\n            return false;\n        }\n        document.body.removeChild(textarea);\n    }\n}\nvar entityIdValue = entityId.id;\nvar data = widgetContext.data.find((el) => el.datasource.entityId === entityIdValue && el.dataKey.name === ''sw_checksum'');\nvar checksum = data.data[0][1];\nconsole.log(checksum);\nif (checksum !== '''') {\n    copyToClipboard(checksum);\n    widgetContext.showSuccessToast(''Software checksum has been copied to clipboard'', 2000, ''top'');\n} else {\n    data = widgetContext.data.find((el) => el.datasource.entityId === entityIdValue && el.dataKey.name === ''sw_url'');\n    var url = data.data[0][1];\n    if (url !== '''') {\n        copyToClipboard(url);\n        widgetContext.showSuccessToast(''Software direct URL has been copied to clipboard'', 2000, ''top'');\n    } else {\n        widgetContext.showToast(''warn'', ''Device '' + entityName +'' has not software set.'', 2000, ''top'');\n    }\n}","id":"09323079-7111-87f7-90d1-c62cd7d85dc7"}]},"showTitleIcon":false,"iconColor":"rgba(0, 0, 0, 0.87)","iconSize":"24px","titleTooltip":"","widgetStyle":{}},"row":0,"col":0,"id":"d2d13e0d-4e71-889f-9343-ad2f0af9f176","typeFullFqn":"system.cards.entities_table"}},"states":{"default":{"name":"Device list","root":true,"layouts":{"main":{"widgets":{"cd03188e-cd9d-9601-fd57-da4cb95fc016":{"sizeX":19,"sizeY":12,"row":0,"col":0},"17543c57-af4a-2c1e-bf12-53a7b46791e6":{"sizeX":5,"sizeY":3,"row":0,"col":19},"6c1c4e1a-bce0-f5ad-ff8b-ba1dfc5a4ec6":{"sizeX":5,"sizeY":3,"row":3,"col":19},"e6674227-9cf3-a2f6-ecac-5ccfc38a3c81":{"sizeX":5,"sizeY":3,"row":9,"col":19},"77b10144-b904-edd5-8c7c-8fb75616c6d8":{"sizeX":5,"sizeY":3,"row":6,"col":19}},"gridSettings":{"backgroundColor":"#eeeeee","color":"rgba(0,0,0,0.870588)","columns":24,"margin":12,"backgroundSizeMode":"100%","autoFillHeight":true,"backgroundImageUrl":null,"mobileAutoFillHeight":true,"mobileRowHeight":70,"outerMargin":true,"layoutType":"default"}}}},"device_software_history":{"name":"Software history: ${entityName}","root":false,"layouts":{"main":{"widgets":{"100b756c-0082-6505-3ae1-3603e6deea48":{"sizeX":24,"sizeY":12,"row":0,"col":0}},"gridSettings":{"backgroundColor":"#eeeeee","color":"rgba(0,0,0,0.870588)","columns":24,"margin":10,"backgroundSizeMode":"100%","autoFillHeight":true,"backgroundImageUrl":null,"mobileAutoFillHeight":false,"mobileRowHeight":70,"outerMar