ialogTitle":"","dialogHideDashboardToolbar":true,"dialogWidth":null,"dialogHeight":null,"openRightLayout":false,"id":"98a1406c-3301-bc2f-2c5d-d637ce3b663b"},{"name":"Edit firmware","icon":"edit","type":"customPretty","customHtml":"<form #editEntityForm=\"ngForm\" [formGroup]=\"editEntityFormGroup\"\n      (ngSubmit)=\"save()\"  class=\"edit-entity-form\">\n  <mat-toolbar class=\"flex flex-row\" color=\"primary\">\n    <h2>Edit firmware {{entityName}}</h2>\n    <span class=\"flex-1\"></span>\n    <button mat-icon-button (click)=\"cancel()\" type=\"button\">\n      <mat-icon class=\"material-icons\">close</mat-icon>\n    </button>\n  </mat-toolbar>\n  <mat-progress-bar color=\"warn\" mode=\"indeterminate\" *ngIf=\"isLoading$ | async\">\n  </mat-progress-bar>\n  <div style=\"height: 4px;\" *ngIf=\"!(isLoading$ | async)\"></div>\n  <div *ngIf=\"entity.deviceProfileId\" mat-dialog-content class=\"flex flex-col\">\n    <tb-ota-package-autocomplete\n        [useFullEntityId]=\"true\"\n        [deviceProfileId]=\"entity.deviceProfileId.id\"\n        formControlName=\"firmwareId\">\n    </tb-ota-package-autocomplete>\n  </div>\n  <div mat-dialog-actions class=\"flex flex-row items-center justify-end\">\n    <button mat-button color=\"primary\"\n            type=\"button\"\n            [disabled]=\"(isLoading$ | async)\"\n            (click)=\"cancel()\" cdkFocusInitial>\n      Cancel\n    </button>\n    <button mat-button mat-raised-button color=\"primary\"\n            type=\"submit\"\n            [disabled]=\"(isLoading$ | async) || editEntityForm.invalid || !editEntityForm.dirty\">\n      Save\n    </button>\n  </div>\n</form>","customCss":"form {\n    min-width: 300px !important;\n}","customFunction":"let $injector = widgetContext.$scope.$injector;\nlet customDialog = $injector.get(widgetContext.servicesMap.get(''customDialog''));\nlet entityService = $injector.get(widgetContext.servicesMap.get(''entityService''));\nlet deviceService = $injector.get(widgetContext.servicesMap.get(''deviceService''));\n\nopenEditEntityDialog();\n\nfunction openEditEntityDialog() {\n    customDialog.customDialog(htmlTemplate, EditEntityDialogController).subscribe();\n}\n\nfunction EditEntityDialogController(instance) {\n    let vm = instance;\n\n    vm.entityName = entityName;\n    vm.entity = {};\n\n    vm.editEntityFormGroup = vm.fb.group({\n        firmwareId: [null]\n    });\n\n    getEntityInfo();\n\n    vm.cancel = function() {\n        vm.dialogRef.close(null);\n    };\n\n    vm.save = function() {\n        vm.editEntityFormGroup.markAsPristine();\n        saveEntity().subscribe(\n            function () {\n                // widgetContext.updateAliases();\n                vm.dialogRef.close(null);\n            }\n        );\n    };\n\n\n    function getEntityInfo() {\n        entityService.getEntity(entityId.entityType, entityId.id).subscribe(\n            function (data) {\n                vm.entity = data;\n                vm.editEntityFormGroup.patchValue({\n                    firmwareId: vm.entity.firmwareId\n                }, {emitEvent: false});\n            }\n        );\n    }\n\n    function saveEntity() {\n        const formValues = vm.editEntityFormGroup.value;\n        vm.entity.firmwareId = formValues.firmwareId;\n        return deviceService.saveDevice(vm.entity);\n    }\n}","customResources":[],"id":"23099c1d-454b-25dc-8bc0-7cf33c21c5d5"},{"name":"Download firmware","icon":"file_download","type":"custom","customFunction":"let $injector = widgetContext.$scope.$injector;\nlet entityService = $injector.get(widgetContext.servicesMap.get(''entityService''));\nlet otaPackageService = $injector.get(widgetContext.servicesMap.get(''otaPackageService''));\nlet deviceProfileService = $injector.get(widgetContext.servicesMap.get(''deviceProfileService''));\n\ngetDeviceFirmware();\n\nfunction getDeviceFirmware() {\n    var entityIdValue = entityId.id;\n    var data = widgetContext.data.find((el) => el.datasource.entityId === entityIdValue && el.dataKey.name === ''fw_url'');\n    var url = data.data[0][1];\n    if (url === '''') {\n        entityService.getEntity(entityId.entityType, entityId.id).subscribe(\n            function (data) {\n                if (data.firmwareId !== null) {\n                    otaPackageService.downloadOtaPackage(data.firmwareId.id).subscribe();    \n                } else {\n                    deviceProfileService.getDeviceProfile(data.deviceProfileId.id).subscribe(\n                        function (deviceProfile) {\n                            if (deviceProfile.firmwareId !== null) {\n                                otaPackageService.downloadOtaPackage(deviceProfile.firmwareId.id).subscribe();\n                            } else {\n                                widgetContext.showToast(''warn'', ''Device '' + entityName +'' has not firmware set.'', 2000, ''top'');\n                            }\n                    });\n                }\n            }\n        );\n    } else {\n        widgetContext.showToast(''warn'', ''Device '' + entityName +'' has not firmware set.'', 2000, ''top'');\n    }\n}","id":"12533058-42f6-e75f-620c-219c48d01ec0"},{"name":"Copy checksum/URL","icon":"content_copy","type":"custom","customFunction":"function copyToClipboard(text) {\n    if (window.clipboardData && window.clipboardData.setData) {\n        return window.clipboardData.setData(\"Text\", text);\n\n    }\n    else if (document.queryCommandSupported && document.queryCommandSupported(\"copy\")) {\n        var textarea = document.createElement(\"textarea\");\n        textarea.textContent = text;\n        textarea.style.position = \"fixed\";\n        document.body.appendChild(textarea);\n        textarea.select();\n        try {\n            return document.execCommand(\"copy\");\n        }\n        catch (ex) {\n            console.warn(\"Copy to clipboard failed.\", ex);\n            return false;\n        }\n        document.body.removeChild(textarea);\n    }\n}\nvar entityIdValue = entityId.id;\nvar data = widgetContext.data.find((el) => el.datasource.entityId === entityIdValue && el.dataKey.name === ''fw_checksum'');\nvar checksum = data.data[0][1];\nif (checksum !== '''') {\n    copyToClipboard(checksum);\n    widgetContext.showSuccessToast(''Firmware checksum has been copied to clipboard'', 2000, ''top'');\n} else {\n    data = widgetContext.data.find((el) => el.datasource.entityId === entityIdValue && el.dataKey.name === ''fw_url'');\n    var url = data.data[0][1];\n    if (url !== '''') {\n        copyToClipboard(url);\n        widgetContext.showSuccessToast(''Firmware direct URL has been copied to clipboard'', 2000, ''top'');\n    } else {\n        widgetContext.showToast(''warn'', ''Device '' + entityName +'' has not firmware set.'', 2000, ''top'');\n    }\n}","id":"09323079-7111-87f7-90d1-c62cd7d85dc7"}]},"showTitleIcon":false,"iconColor":"rgba(0, 0, 0, 0.87)","iconSize":"24px","titleTooltip":"","widgetStyle":{}},"row":0,"col":0,"id":"cd03188e-cd9d-9601-fd57-da4cb95fc016","typeFullFqn":"system.cards.entities_table"},"100b756c-0082-6505-3ae1-3603e6deea48":{"type":"timeseries","sizeX":8,"sizeY":6.5,"config":{"datasources":[{"type":"entity","name":null,"entityAliasId":"19f41c21-d9af-e666-8f50-e1748778f955","filterId":null,"dataKeys":[{"name":"current_fw_title","type":"timeseries","label":"Current firmware title","color":"#2196f3","settings":{"useCellStyleFunction":false,"cellStyleFunction":"","useCellContentFunction":false,"cellContentFunction":""},"_hash":0.5978079905579401,"units":null,"decimals":null,"funcBody":null,"usePostProcessing":null,"postFuncBody":null},{"name":"current_fw_version","type":"timeseries","label":"Current firmware version","color":"#4caf50","settings":{"useCellStyleFunction":false,"cellStyleFunction":"","useCellContentFunction":false,"cellContentFunction":""},"_hash":0.027392025058568192,"units":null,"decimals":null,"funcBody":null,"usePostProcessing":null,"postFuncBody":null},{"name":"target_fw_title","type":"ti