INSERT INTO "dashboard" ("id", "created_time", "configuration", "assigned_customers", "tenant_id", "title", "mobile_hide", "mobile_order", "image", "external_id", "version") VALUES ('f371a590-6570-11f1-9578-071530b96ddb', 1781167122025, '{"widgets":{"f33c746c-0dfc-c212-395b-b448c8a17209":{"type":"latest","sizeX":11,"sizeY":11,"config":{"showTitle":true,"backgroundColor":"rgb(255, 255, 255)","color":"rgba(0, 0, 0, 0.87)","padding":"4px","settings":{"enableSearch":true,"displayPagination":true,"defaultPageSize":10,"defaultSortOrder":"entityName","displayEntityName":true,"displayEntityType":false,"enableSelectColumnDisplay":false,"entitiesTitle":"Thermostats","displayEntityLabel":false,"entityNameColumnTitle":"Thermostat name"},"title":"Thermostats","dropShadow":true,"enableFullscreen":false,"titleStyle":{"fontSize":"16px","fontWeight":400,"padding":"5px 10px 5px 10px"},"showLegend":false,"datasources":[{"type":"entity","name":null,"entityAliasId":"68a058e1-fdda-8482-715b-3ae4a488568e","dataKeys":[{"name":"active","type":"attribute","label":"Active","color":"#2196f3","settings":{"columnWidth":"0px","useCellStyleFunction":true,"useCellContentFunction":true,"cellContentFunction":"value = ''&#11044;'';\nreturn value;","cellStyleFunction":"var color;\nif (value === \"true\") {\n    color = ''rgb(39, 134, 34)'';\n} else {\n    color = ''rgb(255, 0, 0)'';\n}\nreturn {\n    color: color,\n    fontSize: ''18px''\n};"}},{"name":"temperature","type":"timeseries","label":"Temperature","color":"#4caf50","settings":{"columnWidth":"0px","useCellStyleFunction":false,"useCellContentFunction":false},"units":"°C","decimals":1},{"name":"humidity","type":"timeseries","label":"Humidity","color":"#f44336","settings":{"columnWidth":"0px","useCellStyleFunction":false,"useCellContentFunction":false},"units":"%","decimals":0},{"name":"latitude","type":"attribute","label":"latitude","color":"#ffc107","settings":{"columnWidth":"0px","useCellStyleFunction":false,"cellStyleFunction":"","useCellContentFunction":false,"cellContentFunction":""}},{"name":"longitude","type":"attribute","label":"longitude","color":"#607d8b","settings":{"columnWidth":"0px","useCellStyleFunction":false,"cellStyleFunction":"","useCellContentFunction":false,"cellContentFunction":""}}]}],"showTitleIcon":false,"titleIcon":null,"iconColor":"rgba(0, 0, 0, 0.87)","iconSize":"24px","titleTooltip":"","widgetStyle":{},"actions":{"headerButton":[{"id":"85b803db-90f2-5c63-1388-a378e0eb10d6","name":"Edit location","icon":"map","type":"openDashboardState","targetDashboardStateId":"map","setEntityId":false},{"name":"Add","icon":"add","type":"customPretty","customHtml":"<form #addEntityForm=\"ngForm\" [formGroup]=\"addEntityFormGroup\"\n      (ngSubmit)=\"save()\" class=\"add-entity-form\">\n  <mat-toolbar color=\"primary\">\n    <h2>Add thermostat</h2>\n    <span class=\"flex-1\"></span>\n    <button mat-icon-button (click)=\"cancel()\" type=\"button\">\n      <mat-icon class=\"material-icons\">close</mat-icon>\n    </button>\n  </mat-toolbar>\n  <mat-progress-bar color=\"warn\" mode=\"indeterminate\" *ngIf=\"isLoading$ | async\">\n  </mat-progress-bar>\n  <div style=\"height: 4px;\" *ngIf=\"!(isLoading$ | async)\"></div>\n  <div mat-dialog-content class=\"flex flex-col\">\n    <mat-form-field class=\"mat-block flex-1\">\n      <mat-label>Thermostat name</mat-label>\n      <input matInput formControlName=\"entityName\" required>\n      <mat-error *ngIf=\"addEntityFormGroup.get(''entityName'').hasError(''required'')\">\n        Thermostat name is required.\n      </mat-error>\n    </mat-form-field>\n    <div formGroupName=\"attributes\" class=\"flex flex-col\">\n      <mat-slide-toggle formControlName=\"temperatureAlarmFlag\">\n        High temperature alarm\n      </mat-slide-toggle>\n      <mat-form-field class=\"mat-block flex-1\">\n        <mat-label>High temperature threshold, °C</mat-label>\n        <input type=\"number\" step=\"any\" matInput\n               [required] = \"addEntityFormGroup.get(''attributes'').get(''temperatureAlarmFlag'').value\"\n               formControlName=\"temperatureAlarmThreshold\">\n        <mat-error *ngIf=\"addEntityFormGroup.get(''attributes'').get(''temperatureAlarmThreshold'').hasError(''required'')\">\n          High temperature threshold is required.\n        </mat-error>\n      </mat-form-field>\n\n      <mat-slide-toggle formControlName=\"humidityAlarmFlag\">\n        Low humidity alarm\n      </mat-slide-toggle>\n\n      <mat-form-field class=\"mat-block flex-1\">\n        <mat-label>Low humidity threshold, %</mat-label>\n        <input type=\"number\" step=\"any\" matInput\n               [required] = \"addEntityFormGroup.get(''attributes'').get(''humidityAlarmFlag'').value\"\n               formControlName=\"humidityAlarmThreshold\">\n        <mat-error *ngIf=\"addEntityFormGroup.get(''attributes'').get(''humidityAlarmThreshold'').hasError(''required'')\">\n          Low humidity threshold is required.\n        </mat-error>\n      </mat-form-field>\n    </div>\n  </div>\n  <div mat-dialog-actions class=\"flex flex-row items-center justify-end\">\n    <button mat-button mat-raised-button color=\"primary\"\n            type=\"submit\"\n            [disabled]=\"(isLoading$ | async) || addEntityForm.invalid || !addEntityForm.dirty\">\n      Create\n    </button>\n    <button mat-button color=\"primary\"\n            type=\"button\"\n            [disabled]=\"(isLoading$ | async)\"\n            (click)=\"cancel()\" cdkFocusInitial>\n      Cancel\n    </button>\n  </div>\n</form>","customCss":".add-entity-form{\n    width: 300px;\n}\n","customFunction":"let $injector = widgetContext.$scope.$injector;\nlet customDialog = $injector.get(widgetContext.servicesMap.get(''customDialog''));\nlet deviceService = $injector.get(widgetContext.servicesMap.get(''deviceService''));\nlet attributeService = $injector.get(widgetContext.servicesMap.get(''attributeService''));\n\nopenAddEntityDialog();\n\nfunction openAddEntityDialog() {\n    customDialog.customDialog(htmlTemplate, AddEntityDialogController).subscribe();\n}\n\nfunction AddEntityDialogController(instance) {\n    let vm = instance;\n    \n    vm.addEntityFormGroup = vm.fb.group({\n        entityName: ['''', [vm.validators.required]],\n        attributes: vm.fb.group({\n            temperatureAlarmFlag: [false],\n            temperatureAlarmThreshold: [{value: null, disabled: true}],\n            humidityAlarmFlag: [false],\n            humidityAlarmThreshold: [{value: null, disabled: true}]\n        })\n    });\n    \n    vm.addEntityFormGroup.get(''attributes'').get(''temperatureAlarmFlag'').valueChanges\n    .subscribe(activate => {\n        if (activate) {\n            vm.addEntityFormGroup.get(''attributes'').get(''temperatureAlarmThreshold'').enable();\n        } else {\n            vm.addEntityFormGroup.get(''attributes'').get(''temperatureAlarmThreshold'').disable();\n        }\n    });\n    \n    vm.addEntityFormGroup.get(''attributes'').get(''humidityAlarmFlag'').valueChanges\n    .subscribe(activate => {\n        if (activate) {\n            vm.addEntityFormGroup.get(''attributes'').get(''humidityAlarmThreshold'').enable();\n        } else {\n            vm.addEntityFormGroup.get(''attributes'').get(''humidityAlarmThreshold'').disable();\n        }\n    });\n\n    vm.save = function() {\n        vm.addEntityFormGroup.markAsPristine();\n        saveEntityObservable().subscribe(\n            function (entity) {\n                saveAttributes(entity.id).subscribe(\n                    function () {\n                        widgetContext.updateAliases();\n                        vm.dialogRef.close(null);\n                    }\n                );\n            }\n        );\n    };\n    \n    vm.cancel = function() {\n        vm.dialogRef.close(null);\n    };\n    \n    function saveEntityObservable() {\n        const formValues = vm.addEntityFormGroup.value;\n        let entity = {\n            name: formValues.entityName,\n            type: \"thermostat\"\n        };\n        return deviceService.saveDevice(entity);\n    }\n    \n    function saveAttributes(entityId) {\n        let attributes = vm.addEntityFormGroup.get(''attributes'').value;\n        let attributesArray = [];\n        for (let key in attributes) {\n            if(attributes[key] !== null) {\n                attributesArray.push({key: key, value: attributes[key]});\n            }\n        }\n        if (attributesArray.length > 0) {\n            return attributeService.saveEntityAttributes(entityId, \"SERVER_SCOPE\", attributesArray);\n        } else {\n            return widgetContext.rxjs.of([]);\n        }\n    }\n}","customResources":[],"id":"8ab5a518-67d2-b6a2-956d-81fd512294b2"}],"actionCellButton":[{"id":"ca241cd8-788d-5508-a9ce-74b03ef42a7f","name":"Chart","icon":"show_chart","type":"openDashboardState","targetDashboardStateId":"chart","setEntityId":true},{"name":"Edit","icon":"edit","type":"customPretty","customHtml":"<form #editEntityForm=\"ngForm\" [formGroup]=\"editEntityFormGroup\"\n      (ngSubmit)=\"save()\" class=\"edit-entity-form\">\n  <mat-toolbar color=\"primary\">\n    <h2>Edit thermostat {{entityName}}</h2>\n    <span class=\"flex-1\"></span>\n    <button mat-icon-button (click)=\"cancel()\" type=\"button\">\n      <mat-icon class=\"material-icons\">close</mat-icon>\n    </button>\n  </mat-toolbar>\n  <mat-progress-bar color=\"warn\" mode=\"indeterminate\" *ngIf=\"isLoading$ | async\">\n  </mat-progress-bar>\n  <div style=\"height: 4px;\" *ngIf=\"!(isLoading$ | async)\"></div>\n  <div mat-dialog-content class=\"flex flex-col\">\n    <mat-form-field class=\"mat-block flex-1\">\n      <mat-label>Thermostat name</mat-label>\n      <input matInput formControlName=\"entityName\" readonly>\n    </mat-form-field>\n    <div formGroupName=\"attributes\" class=\"flex flex-col\">\n      <mat-slide-toggle formControlName=\"temperatureAlarmFlag\">\n        High temperature alarm\n      </mat-slide-toggle>\n      <mat-form-field class=\"mat-block flex-1\">\n        <mat-label>High temperature threshold, °C</mat-label>\n        <input type=\"number\" step=\"any\" matInput\n               [required] = \"editEntityFormGroup.get(''attributes'').get(''temperatureAlarmFlag'').value\"\n               formControlName=\"temperatureAlarmThreshold\">\n        <mat-error *ngIf=\"editEntityFormGroup.get(''attributes'').get(''temperatureAlarmThreshold'').hasError(''required'')\">\n          High temperature threshold is required.\n        </mat-error>\n      </mat-form-field>\n\n      <mat-slide-toggle formControlName=\"humidityAlarmFlag\">\n        Low humidity alarm\n      </mat-slide-toggle>\n\n      <mat-form-field class=\"mat-block flex-1\">\n        <mat-label>Low humidity threshold, %</mat-label>\n        <input type=\"number\" step=\"any\" matInput\n               [required] = \"editEntityFormGroup.get(''attributes'').get(''humidityAlarmFlag'').value\"\n               formControlName=\"humidityAlarmThreshold\">\n        <mat-error *ngIf=\"editEntityFormGroup.get(''attributes'').get(''humidityAlarmThreshold'').hasError(''required'')\">\n          Low humidity threshold is required.\n        </mat-error>\n      </mat-form-field>\n    </div>\n  </div>\n  <div mat-dialog-actions class=\"flex flex-row items-center justify-end\">\n    <button mat-raised-button color=\"primary\"\n            type=\"submit\"\n            [disabled]=\"(isLoading$ | async) || editEntityForm.invalid || !editEntityForm.dirty\">\n      Save\n    </button>\n    <button mat-button color=\"primary\"\n            type=\"button\"\n            [disabled]=\"(isLoading$ | async)\"\n            (click)=\"cancel()\" cdkFocusInitial>\n      Cancel\n    </button>\n  </div>\n</form>","customCss":".edit-entity-form{\n    width: 300px;\n}","customFunction":"let $injector = widgetContext.$scope.$injector;\nlet customDialog = $injector.get(widgetContext.servicesMap.get(''customDialog''));\nlet attributeService = $injector.get(widgetContext.servicesMap.get(''attributeService''));\n\nopenEditEntityDialog();\n\nfunction openEditEntityDialog() {\n    customDialog.customDialog(htmlTemplate, EditEntityDialogController).subscribe();\n}\n\nfunction EditEntityDialogController(instance) {\n    let vm = instance;\n    \n    vm.entityId = entityId;\n    vm.entityName = entityName;\n    vm.attributes = {};\n    \n    vm.editEntityFormGroup = vm.fb.group({\n        entityName: [''''],\n        attributes: vm.fb.group({\n            temperatureAlarmFlag: [false],\n            temperatureAlarmThreshold: [{value: null, disabled: true}],\n            humidityAlarmFlag: [false],\n            humidityAlarmThreshold: [{value: null, disabled: true}]\n        })\n    });\n    \n    vm.editEntityFormGroup.get(''attributes'').get(''temperatureAlarmFlag'').valueChanges\n    .subscribe(activate => {\n        if (activate) {\n            vm.editEntityFormGroup.get(''attributes'').get(''temperatureAlarmThreshold'').enable();\n        } else {\n            vm.editEntityFormGroup.get(''attributes'').get(''temperatureAlarmThreshold'').disable();\n        }\n    });\n    \n    vm.editEntityFormGroup.get(''attributes'').get(''humidityAlarmFlag'').valueChanges\n    .subscribe(activate => {\n        if (activate) {\n            vm.editEntityFormGroup.get(''attributes'').get(''humidityAlarmThreshold'').enable();\n        } else {\n            vm.editEntityFormGroup.get(''attributes'').get(''humidityAlarmThreshold'').disable();\n        }\n    });\n    \n    \n    getEntityInfo();\n    \n    \n    vm.save = function() {\n        vm.editEntityFormGroup.markAsPristine();\n        saveAttributes(entityId).subscribe(\n            function () {\n                vm.dialogRef.close(null);\n            }\n        );\n    };\n    \n    vm.cancel = function() {\n        vm.dialogRef.close(null);\n    };\n    \n    function getEntityAttributes(attributes) {\n        for (var i = 0; i < attributes.length; i++) {\n            vm.attributes[attributes[i].key] = attributes[i].value;\n        }\n    }\n    \n    function getEntityInfo() {\n        attributeService.getEntityAttributes(entityId, ''SERVER_SCOPE'').subscribe(\n            function (attributes) {\n                getEntityAttributes(attributes);\n                vm.editEntityFormGroup.patchValue({\n                    entityName: vm.entityName,\n                    attributes: vm.attributes\n                });\n                // if(vm.attributes.temperatureAlarmFlag) {\n                //     vm.editEntityFormGroup.get(''attributes'').get(''temperatureAlarmThreshold'').enable();\n                // }\n                // if(vm.attributes.humidityAlarmFlag) {\n                //     vm.editEntityFormGroup.get(''attributes'').get(''humidityAlarmThreshold'').enable();\n                // }\n            }\n        );\n    }\n    \n    function saveAttributes(entityId) {\n        let attributes = vm.editEntityFormGroup.get(''attributes'').value;\n        let attributesArray = [];\n        for (let key in attributes) {\n            if (attributes[key] !== vm.attributes[key]) {\n                attributesArray.push({key: key, value: attributes[key]});\n            }\n        }\n        if (attributesArray.length > 0) {\n            return attributeService.saveEntityAttributes(entityId, \"SERVER_SCOPE\", attributesArray);\n        } else {\n            return widgetContext.rxjs.of([]);\n        }\n    }\n}","customResources":[],"id":"7506576f-87ba-d3a0-88fb-e304d451776d"},{"name":"Delete","icon":"delete","type":"custom","customFunction":"let $injector = widgetContext.$scope.$injector;\nlet dialogs = $injector.get(widgetContext.servicesMap.get(''dialogs''));\nlet deviceService = $injector.get(widgetContext.servicesMap.get(''deviceService''));\n\nopenDeleteEntityDialog();\n\nfunction openDeleteEntityDialog() {\n    let title = ''Delete thermostat \"'' +  entityName + ''\"'';\n    let content = ''Are you sure you want to delete the thermostat \"'' +\n        entityName + ''\"?'';\n    dialogs.confirm(title, content, ''Cancel'', ''Delete'').subscribe(\n        function(result) {\n            if (result) {\n                deleteEntity();\n            }\n        }\n    );\n}\n\nfunction deleteEntity() {\n    deviceService.deleteDevice(entityId.id).subscribe(\n        function success() {\n            widgetContext.updateAliases();\n        },\n        function fail() {\n            showErrorDialog();\n        }\n    );\n}\n\nfunction showErrorDialog() {\n    let title = ''Error'';\n    let content = ''An error occurred while deleting the thermostat. Please try again.'';\n    dialogs.alert(title, content, ''CLOSE'').subscribe(\n        function(result) {}\n    );\n}","id":"3488848b-e47d-6af6-659f-5d78369ece5e"}],"rowClick":[]}},"id":"f33c746c-0dfc-c212-395b-b448c8a17209","typeFullFqn":"system.cards.entities_table"},"7943196b-eedb-d422-f9c3-b32d379ad172":{"type":"alarm","sizeX":13,"sizeY":5,"config":{"timewindow":{"realtime":{"interval":1000,"timewindowMs":86400000},"aggregation":{"type":"NONE","limit":200}},"showTitle":true,"backgroundColor":"rgb(255, 255, 255)","color":"rgba(0, 0, 0, 0.87)","padding":"4px","settings":{"enableSelection":true,"enableSearch":true,"displayDetails":true,"allowAcknowledgment":true,"allowClear":true,"allowAssign":true,"displayComments":true,"displayPagination":true,"defaultPageSize":10,"defaultSortOrder":"-createdTime","enableSelectColumnDisplay":false,"alarmsTitle":"Alarms","enableFilter":true},"title":"New Alarms table","dropShadow":true,"enableFullscreen":false,"titleStyle":{"fontSize":"16px","fontWeight":400,"padding":"5px 10px 5px 2px"},"useDashboardTimewindow":false,"showLegend":false,"alarmSource":{"type":"entity","name":"alarms","entityAliasId":"68a058e1-fdda-8482-715b-3ae4a488568e","filterId":null,"dataKeys":[{"name":"createdTime","type":"alarm","label":"Created time","color":"#2196f3","settings":{}},{"name":"originator","type":"alarm","label":"Originator","color":"#4caf50","s